<?php
$asset_prefix="../";require_once "../config/auth.php";require_role("admin");require_once "../config/database.php";
$msg="";
if($_SERVER['REQUEST_METHOD']==='POST'){try{$pdo->beginTransaction();$pdo->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'lecturer')")->execute([trim($_POST['name']),trim($_POST['email']),password_hash($_POST['password'],PASSWORD_DEFAULT)]);$uid=$pdo->lastInsertId();$pdo->prepare("INSERT INTO lecturers(user_id,lecturer_id) VALUES(?,?)")->execute([$uid,trim($_POST['lecturer_id'])]);$pdo->commit();$msg="Lecturer added.";}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$msg="Email or lecturer ID already exists.";}}
$rows=$pdo->query("SELECT l.*,u.name,u.email FROM lecturers l JOIN users u ON u.id=l.user_id ORDER BY l.id DESC")->fetchAll();
$page_title="Lecturers";include "../partials/header.php";?>
<h2>Lecturers</h2><div class="card p-4 mb-4"><?php if($msg):?><div class="alert alert-info"><?=e($msg)?></div><?php endif;?><form method="post" class="row g-2"><div class="col-md-3"><input name="lecturer_id" class="form-control" placeholder="Lecturer ID" required></div><div class="col-md-3"><input name="name" class="form-control" placeholder="Name" required></div><div class="col-md-3"><input name="email" type="email" class="form-control" placeholder="Email" required></div><div class="col-md-3"><input name="password" type="password" class="form-control" placeholder="Password" required></div><div class="col-12"><button class="btn btn-primary">Add Lecturer</button></div></form></div>
<div class="card p-4"><table class="table"><tr><th>ID</th><th>Name</th><th>Email</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['lecturer_id'])?></td><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td></tr><?php endforeach;?></table></div><?php include "../partials/footer.php"; ?>